M = [x for x in M if x]
bad = 0
for x in M:
    src = open(os.path.join(root, x["file"])).read()
    n = src.count(x["find"])
    if n != 1:
        print("find occurs %d times: %s (%s)" % (n, x["name"], x["file"]), file=sys.stderr)
        bad += 1
names = [x["name"] for x in M]
assert len(set(names)) == len(names), "duplicate mutation names"
